import matplotlib.pyplot as plt


def plot_backdoor_results(training_history):
    epochs_range = range(1, len(training_history["train_loss"]) + 1)

    plt.figure(figsize=(10, 6))
    plt.plot(
        epochs_range,
        training_history["val_f1"],
        label="Clean Validation (F1-Score)",
        color="#2ca02c",
        linewidth=2,
        linestyle="-",
    )
    plt.plot(
        epochs_range,
        training_history["val_asr"],
        label="Attack Success Rate (ASR)",
        color="#d62728",
        linewidth=2,
        linestyle="--",
    )
    plt.plot(
        epochs_range,
        training_history["trade_off_index"],
        label="Trade-Off Index (TOI)",
        color="#1f77b4",
        linewidth=1.5,
        linestyle=":",
    )

    plt.title(
        "Backdoor Attack Analysis during Training", fontsize=14, fontweight="bold", pad=15
    )
    plt.xlabel("Epochs", fontsize=12)
    plt.ylabel("Score (Threshold 0-1)", fontsize=12)
    plt.grid(True, linestyle="--", alpha=0.6)
    plt.ylim(-0.05, 1.05)
    plt.xlim(1, len(epochs_range))
    plt.legend(loc="lower left", fontsize=11, frameon=True, shadow=True)
    plt.tight_layout()
    _dest_dir_19_4 = globals().get('NOTEBOOK_IMAGES_DIR', globals().get('OUTPUT_DIR', '.'))
    os.makedirs(_dest_dir_19_4, exist_ok=True)
    _fig_path_19_4 = os.path.join(
        _dest_dir_19_4, 
        f'cell_19_04.png'
    )
    plt.savefig(_fig_path_19_4, bbox_inches='tight', dpi=150)
    plt.close()
    plt.close("all")


